# Run JEV judgments for op-cozo-store tched classification hits
import json

# Load the states from the previous step
states = json.loads(open('/var/tmp/functional-followthrough/op-cozo-store/_jev_states.json').read()) if False else []

# I'll send JEV requests for each hit with the proper schema
# Using Choice + Noul for each hit

batch_id = 0
requests = []

for i, s in enumerate(states):
    batch_id += 1
    questions = {}

    if "Q1_executable_logic" in s["questions"]:
        questions["is_executable_logic"] = {
            "type": "Choice",
            "options": {
                "yes": "Executable logic with function/branch/parsing/protocol/state handling",
                "no": "Not executable logic — purely a name, string literal, comment, identifier, log text, error text, or feature flag"
            },
            "instructions": s["questions"]["Q1_executable_logic"]["instructions"]
        }

    if "Q2_name_or_literal" in s["questions"]:
        questions["is_name_or_literal"] = {
            "type": "Noul",
            "instructions": s["questions"]["Q2_name_or_literal"]["instructions"]
        }

    if "Q3_bridge_leftover" in s["questions"]:
        questions["is_bridge_leftover"] = {
            "type": "Choice",
            "options": {
                "yes": "This logic existed only to connect the removed bridge binary to this crate",
                "no": "This is active business logic unrelated to the removed bridge"
            },
            "instructions": s["questions"]["Q3_bridge_leftover"]["instructions"]
        }

    if "Q4_threetched_equivalent" in s["questions"]:
        questions["has_threetched_equivalent"] = {
            "type": "Choice",
            "options": {
                "yes_equivalent": "threetched provides the same functionality",
                "yes_differs": "threetched has similar but different behavior",
                "no_equivalent": "threetched does not provide equivalent functionality"
            },
            "instructions": s["questions"]["Q4_threetched_equivalent"]["instructions"]
        }

    if questions:
        requests.append({
            "state": s["state"],
            "questions": questions,
            "metadata": {
                "file": s["file"],
                "line": s["line"],
                "hit": s["hit"],
                "hit_number": i + 1
            }
        })

print(f"Total JEV requests: {len(requests)}")
print(json.dumps(requests[:2], indent=2))

